          </li>
        }
      </ul>
    }
    <form [formGroup]="form" (ngSubmit)="add()" [attr.aria-label]="'Add a plan for ' + personName()">
      <label [for]="'plan-form-amount-' + personId()">Plan amount</label>
      <input [id]="'plan-form-amount-' + personId()" data-testid="plan-form-amount" formControlName="amount"
             inputmode="decimal" autocomplete="off" />
      <label [for]="'plan-form-start-' + personId()">start</label>
      <input [id]="'plan-form-start-' + personId()" type="date" data-testid="plan-form-start" formControlName="start" />
      <label [for]="'plan-form-every-' + personId()">every (days)</label>
      <input [id]="'plan-form-every-' + personId()" data-testid="plan-form-every" formControlName="every"
             inputmode="numeric" autocomplete="off" />
      <label [for]="'plan-form-end-' + personId()">end</label>
      <input [id]="'plan-form-end-' + personId()" type="date" data-testid="plan-form-end" formControlName="end" />
      <button type="submit" data-testid="plan-form-submit" [disabled]="saving()">Add plan</button>
      @if (error(); as err) {
        <p role="alert" data-testid="plan-error">{{ err }}</p>
      }
    </form>
  `,
})
export class PersonPlans {
  readonly personId = input.required<number>();
  readonly personName = input.required<string>();

  protected readonly plans = inject(Plans);
  private readonly sheets = inject(Sheets);

  protected readonly error = signal<string | null>(null);
  protected readonly saving = signal(false);
  protected readonly form = new FormGroup({
    amount: new FormControl('', { nonNullable: true }),
    start: new FormControl('', { nonNullable: true }),
    every: new FormControl('', { nonNullable: true }),
    end: new FormControl('', { nonNullable: true }),
  });

  constructor() {
    // A (re)load of the sheet starts the form afresh.
    toObservable(this.sheets.loaded).pipe(takeUntilDestroyed()).subscribe(() => {
      this.error.set(null);
      this.form.reset({ amount: '', start: '', every: '', end: '' }, { emitEvent: false });
    });
    // An error is removed as soon as its form is changed.
    this.form.valueChanges.pipe(takeUntilDestroyed()).subscribe(() => this.error.set(null));
  }

  protected add(): void {
    // A second submit before the first has answered is ignored, so it records one plan.
    if (this.saving()) return;
    this.error.set(null);
    const sheet = this.sheets.current();
    if (!sheet) return;
    const value = this.form.getRawValue();
    const amount = value.amount.trim();
    const every = value.every.trim();
    const start = value.start.trim() === '' ? sheet.today : value.start.trim();
    if (!AMOUNT_PATTERN.test(amount)) {
      this.error.set('Type an amount of zero or more with up to two decimals.');
      return;
    }
    if (!EVERY_PATTERN.test(every) || Number(every) < 1) {
      this.error.set('Type the days between claims as a whole number of 1 or more.');
      return;
    }
    if (value.end === '') {
      this.error.set('Choose the plan\'s end date.');
      return;
    }
    if (value.end < start) {
      this.error.set('The plan\'s end cannot be before its start.');
      return;
    }
    this.saving.set(true);
    this.plans.add(sheet.id, this.personId(), { amount, start: value.start === '' ? null : value.start, every: Number(every), end: value.end })
      .subscribe({
        next: () => {
          this.saving.set(false);
          this.form.reset({ amount: '', start: '', every: '', end: '' }, { emitEvent: false });
        },
        error: () => {
          this.saving.set(false);
          this.error.set('Could not add that plan.');
        },
      });
  }
}

// The button that makes the DRAFT claims the sheet's plans are due, and how many the last press made.
@Component({
  selector: 'app-plan-generate',
  template: `
    <p>
      <button type="button" data-testid="plan-generate" (click)="generate()" [disabled]="running()">Generate plan claims</button>
      @if (made() !== null) {
        Made <span data-testid="plan-generated-count">{{ made() }}</span>
      }
      @if (error(); as err) {
        <span role="alert" data-testid="plan-generate-error">{{ err }}</span>
      }
    </p>
  `,
})
export class PlanGenerate {
  /** The claims a press made, in the order made. */
  readonly generated = output<ClaimView[]>();

  private readonly plans = inject(Plans);
  private readonly sheets = inject(Sheets);

  protected readonly running = signal(false);
  /** How many claims the last press made; null while one runs or before any. */
  protected readonly made = signal<number | null>(null);
  protected readonly error = signal<string | null>(null);

  constructor() {
    toObservable(this.sheets.loaded).pipe(takeUntilDestroyed()).subscribe(() => {
      this.made.set(null);
      this.error.set(null);
    });
  }

  protected generate(): void {
    if (this.running()) return;
    this.made.set(null);
    this.error.set(null);
    const sheet = this.sheets.current();
    if (!sheet) return;
    this.running.set(true);
    this.plans.generate(sheet.id).subscribe({
      next: (done) => {
        this.running.set(false);
        this.generated.emit(done.claims);
        this.made.set(done.made);
      },
      error: () => {
        this.running.set(false);
        this.error.set('Could not generate the plans\' claims.');
      },
    });
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, computed, inject, signal } from '@angular/core';
import { Observable, tap } from 'rxjs';
import { ClaimView } from './claims';

/** A person's plan: an amount claimed on its start date and every `every` days after, up to its end date, with how
 *  many claims it has made so far. */
export interface PlanView {
  id: number;
  personId: number;
  amount: string;
  start: string;
  every: number;
  end: string;
  generated: number;
}

/** A plan as its form submits it; a blank start takes the sheet's today. */
export interface PlanForm {
  amount: string;
  start: string | null;
  every: number;
  end: string;
}

/** What a generate did: how many claims it made, the claims in the order made, and the sheet's plans. */
export interface GeneratedView {
  made: number;
  claims: ClaimView[];
  plans: PlanView[];
}

const NO_PLANS: PlanView[] = [];

// The plans on the active sheet, in the order they were added.
@Injectable({ providedIn: 'root' })
export class Plans {
  private readonly http = inject(HttpClient);
  private readonly list = signal<PlanView[]>([]);
  readonly all = this.list.asReadonly();

  /** Each person's plans, by person. */
  private readonly byPerson = computed(() => {
    const map = new Map<number, PlanView[]>();
    for (const p of this.list()) map.set(p.personId, [...(map.get(p.personId) ?? []), p]);
    return map;
  });

  of(personId: number): PlanView[] {
    return this.byPerson().get(personId) ?? NO_PLANS;
  }

  /** Re-read a sheet's plans from the store. */
  load(sheetId: string): Observable<PlanView[]> {
    return this.http.get<PlanView[]>(`${this.base(sheetId)}/plans`).pipe(tap((list) => this.list.set(list)));
  }

  clear(): void {
    this.list.set([]);
  }

  /** Add a plan for the person; refused when the amount or interval is bad or the end is before the start. */
  add(sheetId: string, personId: number, plan: PlanForm): Observable<PlanView> {
    return this.http.post<PlanView>(`${this.base(sheetId)}/people/${personId}/plans`, plan).pipe(
      tap((added) => this.list.update((list) => [...list, added])),
    );
  }

  /** Make the DRAFT claims every plan on the sheet is due, up to its end and the sheet's today. */
  generate(sheetId: string): Observable<GeneratedView> {
    return this.http.post<GeneratedView>(`${this.base(sheetId)}/plans/generate`, null).pipe(
      tap((done) => this.list.set(done.plans)),
    );
  }

  private base(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}`;
  }
}

